To evaluate an arithmetic expression without using `eval` or `exec`, we can implement a simple parser that handles the precedence and associativity of operators. We'll use the Shunting Yard algorithm to convert the infix expression to postfix (Reverse Polish Notation) and then evaluate the postfix expression.

Here's the implementation:

```python
def evaluate(expr: str) -> int:
    def precedence(op):
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators, values):
        right = values.pop()
        left = values.pop()
        operator = operators.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left // right)  # Integer division truncates toward zero

    def greater_precedence(op1, op2):
        return precedence(op1) > precedence(op2) or (precedence(op1) == precedence(op2) and op1 in ('*', '/'))

    def shunting_yard(expression):
        operators = []
        values = []
        i = 0
        while i < len(expression):
            if expression[i].isdigit():
                num = 0
                while i < len(expression) and expression[i].isdigit():
                    num = num * 10 + int(expression[i])
                    i += 1
                values.append(num)
                continue
            if expression[i] == ' ':
                i += 1
                continue
            if expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Pop the '('
            else:
                while (operators and operators[-1] != '(' and
                       greater_precedence(operators[-1], expression[i])):
                    apply_operator(operators, values)
                operators.append(expression[i])
            i += 1
        while operators:
            apply_operator(operators, values)
        return values[0]

    return shunting_yard(expr)

# Example usage:
# print(evaluate("3 + 5 * (10 - 4)"))  # Output: 33
```

Final answer: `evaluate`

